package com.regcode.collection;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class LineWorkerStoreTest {
 static final String A="00000000000000000000000000000001",B="00000000000000000000000000000002",C="00000000000000000000000000000003";
 static JSONObject context(){return new JSONObject().put("mode","production").put("lineWorkflow",true).put("productId",1).put("taskId",0).put("batchNo","A").put("produceDate","2026-10-12").put("expireDate","2027-10-12");}
 static WorkerStore ready(QueueStoreTest.Jdbc db)throws Exception{WorkerStore w=new WorkerStore(db);String cache="line-cache";w.stage(cache,"products",new JSONArray().put(new JSONObject().put("id",1).put("name","product")));JSONArray tasks=new JSONArray();for(int id:new int[]{1,2})tasks.put(new JSONObject().put("id","task-"+id).put("task_id",id).put("task_name","task"+id).put("line_name","line"+id).put("product_id",1).put("state","ready"));w.stage(cache,"pools",tasks);JSONArray codes=new JSONArray();int i=0;for(String code:new String[]{A,B,C})codes.put(new JSONObject().put("pool_id","task-"+(++i==3?2:1)).put("code",code).put("state","reserved"));w.stage(cache,"codes",codes);w.commitCache(new JSONObject().put("id",cache).put("expiresAt",Long.MAX_VALUE).put("products",1).put("pools",2).put("codes",3));return w;}
 @Test public void firstValidCodeInfersTaskAndWrongLineCannotSwitch()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),WorkerStoreTest.profile(1),1);assertEquals("invalid",w.capture("broken",WorkerStoreTest.profile(1),2).getString("kind"));assertEquals(0,w.currentRun().getJSONObject("context").getInt("taskId"));assertEquals("valid",w.capture("half?anything="+A,WorkerStoreTest.profile(1),3).getString("kind"));assertEquals(1,w.currentRun().getJSONObject("context").getInt("taskId"));assertEquals("line1",w.currentRun().getJSONObject("context").getString("lineName"));assertEquals("invalid",w.capture(C,WorkerStoreTest.profile(1),4).getString("kind"));assertEquals(1,w.currentRun().getJSONObject("context").getInt("taskId"));assertEquals("duplicate",w.capture("other?code="+A,WorkerStoreTest.profile(1),5).getString("kind"));assertEquals(1,w.snapshot(1).getJSONObject("counts").getInt("collected"));}}
 @Test public void handoverPreservesTaskAndExportDoesNotPretendToBeAnotherWorker()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);String run=w.start(context(),WorkerStoreTest.profile(1),1).getString("id");w.capture(A,WorkerStoreTest.profile(1),2);w.handover(1);w.resume(run,WorkerStoreTest.profile(2),3);w.capture(B,WorkerStoreTest.profile(2),4);w.finish(2);JSONArray export=w.productionExport(run,1);assertEquals(1,export.length());assertEquals(1,export.getJSONObject(0).getJSONArray("events").length());assertEquals(2,export.getJSONObject(0).getJSONObject("run").getJSONArray("sessions").length());assertTrue(export.getJSONObject(0).getJSONObject("run").getBoolean("sealed"));assertFalse(export.toString().contains("password"));assertFalse(export.toString().contains("credential"));assertEquals(1,export.getJSONObject(0).getJSONObject("run").getJSONObject("context").getInt("taskId"));}}
 @Test public void newLocalCaptureDoesNotReusePreviouslyProducedTaskCode()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),WorkerStoreTest.profile(1),1);w.capture(A,WorkerStoreTest.profile(1),2);w.finish(1);w.start(context(),WorkerStoreTest.profile(2),3);assertEquals("duplicate",w.capture(A,WorkerStoreTest.profile(2),4).getString("kind"));assertEquals("valid",w.capture(B,WorkerStoreTest.profile(2),5).getString("kind"));}}
}
